import React from 'react';
import { render, screen } from '@testing-library/react';
import TadaDeliveryBebidas from './TadaDeliveryBebidas';

describe('TadaDeliveryBebidas', () => {
  test('should render without crashing', () => {
    render(<TadaDeliveryBebidas />);
    expect(screen.getByTestId('TadaDeliveryBebidasIcon')).toBeInTheDocument();
  });
  test('should render icon variant without crashing', () => {
    render(<TadaDeliveryBebidas variant="icon" colorType="onDarkBg" />);
    expect(screen.getByTitle('Tada Delivery Bebidas Icon')).toBeInTheDocument();
  });
  test('should render vertical variant without crashing', () => {
    render(<TadaDeliveryBebidas variant="vertical" colorType="onDarkBg" />);
    expect(screen.getByTitle('Tada Delivery Bebidas Vertical Logo')).toBeInTheDocument();
  });
  test('should render with a different colorType without crashing', () => {
    render(<TadaDeliveryBebidas colorType="onColorBg" />);
    expect(screen.getByTestId('TadaDeliveryBebidasIcon')).toBeInTheDocument();
  });
});
